margin = ops.sub(ops.sub(lpw, lpl), ops.mul(beta, adv_norm))
clamped_margin = ops.clamp(margin, -clip_val, clip_val)
scaled_margin = ops.mul(alpha, clamped_margin)
losses = ops.neg(ops.logsigmoid(scaled_margin))
if batch.get('weight') is not None:
    weighted_losses = ops.mul(batch['weight'], losses)
else:
    weighted_losses = losses
return ops.mean(weighted_losses)

